```js
// Round half-up to 2 decimals. Shifting the decimal point through the
// string form avoids binary error: 1.005 * 100 is 100.49999999999999,
// but "1.005e2" is exactly 100.5, which rounds to 101.
function roundHalfUpCents(n) {
  const s = String(n);
  if (s.includes('e')) {
    // Exponent notation (very small or very large values) can't be shifted this way.
    return Math.round(n * 100) / 100;
  }
  return Number(Math.round(Number(s + 'e2')) + 'e-2');
}

function total(items) {
  const sum = items.reduce((s, i) => s + i.price * i.qty, 0);
  return roundHalfUpCents(sum).toFixed(2);
}

module.exports = { total };
```

